+
+    h1 {
+      margin: 0 0 12px;
+      font-size: 1.75rem;
+      line-height: 1.2;
+    }
+
+    .intro {
+      margin: 0 0 24px;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 16px;
+      border: 1px solid rgba(150, 173, 255, 0.18);
+      border-radius: 16px;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 1.1rem;
+      height: 1.1rem;
+      margin: 0.15rem 0 0;
+      accent-color: var(--accent);
+      cursor: pointer;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+      cursor: pointer;
+    }
+
+    .helper-text {
+      margin: 0;
+      padding-left: calc(1.1rem + 12px);
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 0.9rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #08101f;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      cursor: pointer;
+      transition: transform 140ms ease, filter 140ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.06);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid var(--accent-strong);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--muted);
+    }
+
+    .status.success {
+      padding: 10px 12px;
+      border: 1px solid var(--success-border);
+      border-radius: 12px;
+      background: var(--success-bg);
+      color: var(--success-text);
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 24px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button,
+      .status.success {
+        border-color: ButtonText;
+      }
+
+      .card,
+      .form-field,
+      .status.success {
+        background: Canvas;
+      }
+
+      body {
+        background: Canvas;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a href="#main-content" style="position:absolute;left:-9999px;top:auto;">Skip to main content</a>
+  <div id="root"></div>
+
+  <script>
+    function createElement(tag, props) {
+      var element = document.createElement(tag);
+      var options = props || {};
+
+      Object.keys(options).forEach(function (key) {
+        var value = options[key];
+
+        if (key === "className") {
+          element.className = value;
+        } else if (key === "text") {
+          element.textContent = value;
+        } else if (key === "children") {
+          value.forEach(function (child) {
+            if (typeof child === "string") {
+              element.appendChild(document.createTextNode(child));
+            } else if (child) {
+              element.appendChild(child);
+            }
+          });
+        } else if (key.slice(0, 2) === "on" && typeof value === "function") {
+          element.addEventListener(key.slice(2).toLowerCase(), value);
+        } else if (value === true) {
+          element.setAttribute(key, "");
+        } else if (value !== false && value != null) {
+          element.setAttribute(key, value);
+        }
+      });
+
+      return element;
+    }
+
+    function ConsentField() {
+      var checkbox = createElement("input", {
+        id: "terms-consent",
+        type: "checkbox",
+        name: "termsConsent",
+        required: true,
+        "aria-describedby": "terms-helper"
+      });
+
+      var label = createElement("label", {
+        for: "terms-consent",
+        text: "I agree to the terms of use."
+      });
+
+      var helper = createElement("p", {
+        id: "terms-helper",
+        className: "helper-text",
+        text: "Required to continue."
+      });
+
+      return createElement("div", {
+        className: "form-field",
+        children: [
+          createElement("div", {
+            className: "checkbox-row",
+            children: [checkbox, label]
+          }),
+          helper
+        ]
+      });
+    }
+
+    function App() {
+      var status = createElement("p", {
+        id: "form-status",
+        className: "status",
+        "aria-live": "polite"
+      });
+
+      var form = createElement("form", {
+        children: [
+          ConsentField(),
+          createElement("button", {
+            type: "submit",
+            text: "Submit"
+          }),
+          status
+        ],
+        onsubmit: function (event) {
+          event.preventDefault();
+
+          if (!event.currentTarget.reportValidity()) {
+            return;
+          }
+
+          status.className = "status success";
+          status.textContent = "Consent recorded successfully.";
+        }
+      });
+
+      return createElement("main", {
+        id: "main-content",
+        className: "page",
+        children: [
+          createElement("section", {
+            className: "card",
+            children: [
+              createElement("h1", { text: "Review and confirm" }),
+              createElement("p", {
+                className: "intro",
+                text: "Please confirm your agreement before submitting."
+              }),
+              form
+            ]
+          })
+        ]
+      });
+    }
+
+    document.getElementById("root").appendChild(App());
+  </script>
+</body>
+</html>
*** End Patch
