 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Terms of Use Consent</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #141b31;
       --panel-border: #2b3558;
       --text: #f2f5ff;
       --muted: #aab5d6;
       --accent: #7c9cff;
       --accent-strong: #96adff;
       --success-bg: #13261f;
       --success-border: #2b6c55;
       --success-text: #b9f5d9;
       --shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 35%),
         linear-gradient(180deg, #0c1224 0%, var(--bg) 100%);
       color: var(--text);
     }

     .skip-link {
       position: absolute;
       top: 12px;
       left: 12px;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--accent-strong);
       color: #08101f;
       font-weight: 700;
       text-decoration: none;
       transform: translateY(-160%);
       transition: transform 140ms ease;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page {
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .card {
       width: min(100%, 420px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
       background-color: var(--panel);
       box-shadow: var(--shadow);
     }

     h1 {
       margin: 0 0 12px;
       font-size: 1.75rem;
       line-height: 1.2;
     }

     .intro {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 10px;
       padding: 16px;
       border: 1px solid rgba(150, 173, 255, 0.18);
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.02);
     }

     .checkbox-row {
       display: flex;
       align-items: flex-start;
       gap: 12px;
     }

     input[type="checkbox"] {
       width: 1.1rem;
       height: 1.1rem;
       margin: 0.15rem 0 0;
       accent-color: var(--accent);
       cursor: pointer;
     }

     label {
       font-weight: 600;
       line-height: 1.5;
       cursor: pointer;
     }

     .helper-text {
       margin: 0;
